import { Point, BBox } from '../../types/geometry';

export const distanceSq = (p1: Point, p2: Point) => (p1.x - p2.x)**2 + (p1.y - p2.y)**2;
export const distance = (p1: Point, p2: Point) => Math.sqrt(distanceSq(p1, p2));

export const rayIntersectsSegment = (p: Point, a: Point, b: Point): boolean => {
  if ((a.y > p.y) !== (b.y > p.y)) {
    const intersectX = a.x + (p.y - a.y) * (b.x - a.x) / (b.y - a.y);
    if (intersectX > p.x) {
      return true;
    }
  }
  return false;
};

export const polygonArea = (vertices: Point[]): number => {
  let area = 0;
  for (let i = 0; i < vertices.length; i++) {
    const j = (i + 1) % vertices.length;
    area += vertices[i].x * vertices[j].y;
    area -= vertices[j].x * vertices[i].y;
  }
  return Math.abs(area / 2);
};

export const polygonCenter = (vertices: Point[]): Point => {
  let x = 0, y = 0;
  for(const v of vertices) { x += v.x; y += v.y; }
  return { x: x / vertices.length, y: y / vertices.length };
};

import { Point, SnapMode, SnapResult, SnapTarget, PartGeometry } from '../../types/geometry';
import { distanceSq } from '../math/mathUtils';
import { ProcessedGeometry, Segment } from '../geometry';

const getNormalizedSegment = (p1: Point, p2: Point) => {
  const angle = Math.atan2(p2.y - p1.y, p2.x - p1.x) * 180 / Math.PI;
  return { p1, p2, angle, wasNormalized: false };
};

const distanceToSegmentSq = (p: Point, seg: Segment) => {
  if (seg.type === 'arc' && seg.center && seg.radius) {
    const distToCenter = Math.sqrt(distanceSq(p, seg.center));
    const distToCurve = Math.abs(distToCenter - seg.radius);
    const l2 = distanceSq(seg.p1, seg.p2);
    if (l2 === 0) return distanceSq(p, seg.p1);
    let t = ((p.x - seg.p1.x) * (seg.p2.x - seg.p1.x) + (p.y - seg.p1.y) * (seg.p2.y - seg.p1.y)) / l2;
    if (t >= 0 && t <= 1) return distToCurve * distToCurve;
    return Math.min(distanceSq(p, seg.p1), distanceSq(p, seg.p2));
  }
  const l2 = distanceSq(seg.p1, seg.p2);
  if (l2 === 0) return distanceSq(p, seg.p1);
  let t = ((p.x - seg.p1.x) * (seg.p2.x - seg.p1.x) + (p.y - seg.p1.y) * (seg.p2.y - seg.p1.y)) / l2;
  t = Math.max(0, Math.min(1, t));
  const proj = { x: seg.p1.x + t * (seg.p2.x - seg.p1.x), y: seg.p1.y + t * (seg.p2.y - seg.p1.y) };
  return distanceSq(p, proj);
};

export const findClosestSegment = (point: Point, geometry: ProcessedGeometry | null, threshold: number = 100) => {
  if (!geometry) return null;
  let closest = null;
  const partWidth = geometry.bbox.maxX - geometry.bbox.minX;
  const effectiveThresholdSq = (threshold * (partWidth > 0 ? Math.max(0.1, partWidth / 500) : 1))**2;
  let minDst = effectiveThresholdSq;

  geometry.segments.forEach(seg => {
    const d2 = distanceToSegmentSq(point, seg);
    if (d2 < minDst) {
      minDst = d2;
      closest = getNormalizedSegment(seg.p1, seg.p2);
    }
  });
  return closest;
};

export const findSnapPoint = (mousePoint: Point, processed: ProcessedGeometry | null, mode: SnapMode): SnapResult | null => {
  if (mode === SnapMode.Off || !processed) return null;
  const { vertices, segments, holeCenters, bbox } = processed;

  if (mode === SnapMode.ShapeCenter) {
    if (!holeCenters || holeCenters.length === 0) return null;
    let closest = null, minD = Infinity;
    holeCenters.forEach(c => {
      const d = distanceSq(mousePoint, c.point);
      if (d < minD) { minD = d; closest = c; }
    });
    return closest ? { point: closest.point, angle: 0, snapTarget: 'middle', wasNormalized: false, forceRotation: closest.rotation } : null;
  }

  let closestDistSq = Infinity, snapResult: SnapResult | null = null;
  const snapRadius = 25; 

  const updateBest = (pt: Point, angle: number, target: SnapTarget, norm: boolean) => {
    const d = distanceSq(mousePoint, pt);
    if (d < closestDistSq) { closestDistSq = d; snapResult = { point: pt, angle, snapTarget: target, wasNormalized: norm }; }
  };

  if (mode === SnapMode.Vertex) {
    vertices.forEach(v => {
      const segs = segments.filter(s => distanceSq(s.p1, v) < 1e-9 || distanceSq(s.p2, v) < 1e-9);
      if (segs.length > 0) {
        const best = segs.sort((a,b) => distanceToSegmentSq(mousePoint, a) - distanceToSegmentSq(mousePoint, b))[0];
        const info = getNormalizedSegment(best.p1, best.p2);
        updateBest(v, info.angle, distanceSq(v, info.p1) < 1e-9 ? 'start' : 'end', false);
      }
    });
  } else if (mode === SnapMode.SegmentCenter) {
    segments.forEach(s => {
      const c = { x: (s.p1.x + s.p2.x)/2, y: (s.p1.y + s.p2.y)/2 };
      updateBest(c, getNormalizedSegment(s.p1, s.p2).angle, 'middle', false);
    });
  }

  const partW = bbox.maxX - bbox.minX;
  if (snapResult && closestDistSq < (snapRadius * Math.max(0.1, partW / 500))**2) return snapResult;
  return null;
};

import { useState, useEffect, useRef } from 'react';
import { PunchOp } from '../types/tooling';

export const useSimulationState = (optimizedOperations: PunchOp[] | null) => {
  const [simulationStep, setSimulationStep] = useState<number>(0);
  const [isSimulating, setIsSimulating] = useState<boolean>(false);
  const [simulationSpeed, setSimulationSpeed] = useState<number>(50);
  const simulationInterval = useRef<number | null>(null);

  useEffect(() => {
    setSimulationStep(0);
    setIsSimulating(false);
  }, [optimizedOperations]);

  useEffect(() => {
    if (isSimulating && optimizedOperations) {
      simulationInterval.current = window.setInterval(() => {
        setSimulationStep(prev => {
          if (prev >= optimizedOperations.length - 1) {
            setIsSimulating(false);
            return prev;
          }
          return prev + 1;
        });
      }, simulationSpeed);
    } else {
      if (simulationInterval.current) clearInterval(simulationInterval.current);
    }
    return () => { if (simulationInterval.current) clearInterval(simulationInterval.current); };
  }, [isSimulating, optimizedOperations, simulationSpeed]);

  const toggleSimulation = () => setIsSimulating(!isSimulating);
  const stopSimulation = () => { setIsSimulating(false); setSimulationStep(0); };
  const stepSimulation = (val: number) => {
    setIsSimulating(false);
    if (optimizedOperations) setSimulationStep(Math.max(0, Math.min(val, optimizedOperations.length - 1)));
  };

  return {
    simulationStep,
    isSimulating,
    simulationSpeed,
    setSimulationSpeed,
    toggleSimulation,
    stopSimulation,
    stepSimulation
  };
};

