import React, { useState, useEffect, useRef } from 'react';
import { Tool, ToolShape, PunchType } from '../types';
import { SaveIcon, TrashIcon, FolderIcon, PlusIcon } from './Icons';
import { ModalInputField } from './common/InputField';
import { getPunchTypeName } from '../utils/helpers';
import { parseDxf, dxfEntitiesToSvg } from '../services/dxfParser';

interface ToolFormProps {
  editingTool: Tool | Omit<Tool, 'id'>;
  onSave: (tool: Tool) => void;
  onDelete: (toolId: string) => void;
  onCancel: () => void;
}

export const ToolForm: React.FC<ToolFormProps> = ({ editingTool, onSave, onDelete, onCancel }) => {
  const [formData, setFormData] = useState<Tool | Omit<Tool, 'id'>>(editingTool);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => { setFormData(JSON.parse(JSON.stringify(editingTool))); }, [editingTool]);

  useEffect(() => {
    if (formData.shape === ToolShape.Circle || formData.shape === ToolShape.Square) {
      setFormData(prev => ({ ...prev, height: prev.width }));
    }
  }, [formData.width, formData.shape]);

  const handleFormChange = (field: keyof Tool, value: any) => setFormData(prev => ({ ...prev, [field]: value }));
  const handleDieChange = (index: number, value: number) => {
    const newDies = [...formData.dies];
    newDies[index] = { clearance: value };
    handleFormChange('dies', newDies);
  };

  const handleDxfUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const entities = parseDxf(e.target?.result as string);
        const { path, width, height } = dxfEntitiesToSvg(entities);
        if (width > 0) handleFormChange('width', parseFloat(width.toFixed(3)));
        if (height > 0) handleFormChange('height', parseFloat(height.toFixed(3)));
        handleFormChange('customPath', path);
        handleFormChange('shape', ToolShape.Special);
      } catch (err) { alert("Error parsing DXF"); }
    };
    reader.readAsText(file);
  };

  const isNew = !('id' in formData);

  return (
    <div className="bg-gray-700 p-4 rounded-lg flex flex-col h-full">
      <h3 className="text-xl font-bold mb-4 border-b border-gray-600 pb-2">{isNew ? 'Новый инструмент' : 'Редактирование'}</h3>
      <div className="flex-1 overflow-y-auto pr-2 space-y-4">
        <fieldset className="border border-gray-600 p-3 rounded-md">
          <legend className="px-2 font-semibold text-gray-300">Основное</legend>
          <div className="grid grid-cols-2 gap-4">
            <div className="col-span-2"><ModalInputField label="Название" value={formData.name} onChange={e => handleFormChange('name', e.target.value)} /></div>
            <div>
              <label className="block text-sm font-medium text-gray-300 mb-1">Форма</label>
              <select value={formData.shape} onChange={e => handleFormChange('shape', e.target.value)} className="w-full bg-gray-900 border border-gray-600 rounded px-3 py-2">
                {Object.values(ToolShape).map(s => <option key={s} value={s}>{s}</option>)}
              </select>
            </div>
            {formData.shape === ToolShape.Special && (
              <div className="col-span-2 p-3 border border-dashed border-gray-500 rounded text-center">
                <button onClick={() => fileInputRef.current?.click()} className="px-3 py-1 bg-purple-700 rounded text-sm flex items-center mx-auto space-x-2">
                  <FolderIcon className="w-4 h-4"/> <span>DXF Контур</span>
                </button>
                <input type="file" ref={fileInputRef} onChange={handleDxfUpload} accept=".dxf" className="hidden" />
              </div>
            )}
            <ModalInputField label="Ширина" type="number" value={formData.width} onChange={e => handleFormChange('width', parseFloat(e.target.value)||0)} />
            <ModalInputField label="Высота" type="number" value={formData.height} onChange={e => handleFormChange('height', parseFloat(e.target.value)||0)} disabled={formData.shape === ToolShape.Circle || formData.shape === ToolShape.Square} />
            <div className="col-span-2">
              <label className="block text-sm font-medium text-gray-300 mb-1">Применение</label>
              <select value={formData.punchType} onChange={e => handleFormChange('punchType', e.target.value)} className="w-full bg-gray-900 border border-gray-600 rounded px-3 py-2">
                {Object.values(PunchType).map(pt => <option key={pt} value={pt}>{getPunchTypeName(pt)}</option>)}
              </select>
            </div>
          </div>
        </fieldset>
        <fieldset className="border border-gray-600 p-3 rounded-md">
          <legend className="px-2 font-semibold text-gray-300">Матрицы</legend>
          {formData.dies.map((die, i) => (
            <div key={i} className="flex items-center space-x-2 mb-2">
              <ModalInputField label={`Зазор ${i+1}`} type="number" value={die.clearance} onChange={e => handleDieChange(i, parseFloat(e.target.value)||0)} />
              <button onClick={() => handleFormChange('dies', formData.dies.filter((_, idx) => idx !== i))} className="p-2 bg-red-800 rounded mt-6" disabled={formData.dies.length <= 1}><TrashIcon className="w-4 h-4" /></button>
            </div>
          ))}
          <button onClick={() => handleFormChange('dies', [...formData.dies, { clearance: 0.2 }])} className="text-xs bg-gray-600 px-2 py-1 rounded">Добавить</button>
        </fieldset>
      </div>
      <div className="flex-none pt-4 border-t border-gray-600 flex justify-end space-x-3">
        <button onClick={onCancel} className="px-4 py-2 bg-gray-600 rounded">Отмена</button>
        {!isNew && <button onClick={() => onDelete((formData as Tool).id)} className="px-4 py-2 bg-red-800 rounded">Удалить</button>}
        <button onClick={() => onSave(formData as Tool)} className="px-4 py-2 bg-blue-600 rounded flex items-center space-x-2">
          <SaveIcon className="w-5 h-5"/> <span>Сохранить</span>
        </button>
      </div>
    </div>
  );
};

