import { Header } from './components/Header';
import { Sidebar } from './components/Sidebar';
import { RightPanel } from './components/RightPanel';
import { CanvasArea } from './components/CanvasArea';
import { ToolLibraryView } from './components/ToolLibraryView';
import { TurretSetupView } from './components/TurretSetupView';
import { ScriptLibraryView } from './components/ScriptLibraryView';
import { PartLibraryView } from './components/PartLibraryView';
import { MachineSetupView } from './components/MachineSetupView';
import { AutoPunchSettingsModal } from './components/AutoPunchSettingsModal';
import { GCodeModal } from './components/GCodeModal';
import { OptimizerSettingsModal } from './components/OptimizerSettingsModal';
import { TeachCycleSaveModal } from './components/TeachCycleSaveModal';
import { ConfirmationModal } from './components/common/ConfirmationModal';
import { ToastContainer } from './components/common/Toast';

import { generateContourPunches } from './services/punching';
import { nestingGenerator } from './services/nesting';
import { generateGCode, calculateOptimizedPath } from './services/gcode';
import { getGeometryFromEntities, findClosestSegment } from './services/geometry';
import { generateParametricScript } from './services/scriptGenerator';
import { createTeachCycleFromSelection } from './services/teachLogic';

const App: React.FC = () => {
    const [mode, setMode] = useState<AppMode>(AppMode.PartEditor);

    const [tools, setTools] = useLocalStorage<Tool[]>('fp_tools', initialTools);
    const [parts, setParts] = useLocalStorage<Part[]>('fp_parts', initialParts);
    const [scripts, setScripts] = useLocalStorage<ParametricScript[]>('fp_scripts', initialScripts);
    const [nests, setNests] = useLocalStorage<NestLayout[]>('fp_nests', initialNests);
    const [turretLayouts, setTurretLayouts] = useLocalStorage<TurretLayout[]>('fp_turret_layouts', initialTurretLayouts);
    const [machineSettings, setMachineSettings] = useLocalStorage<MachineSettings>('fp_machine_settings', defaultMachineSettings);
    const [optimizerSettings, setOptimizerSettings] = useLocalStorage<OptimizerSettings>('fp_optimizer_settings', defaultOptimizerSettings);
    const [teachCycles, setTeachCycles] = useLocalStorage<TeachCycle[]>('fp_teach_cycles', []);

    const [activePart, setActivePart] = useState<Part | null>(null);
    const [activeNestId, setActiveNestId] = useState<string | null>(initialNests[0]?.id || null);
    const [activeSheetIndex, setActiveSheetIndex] = useState<number>(0);
    const [selectedPunchId, setSelectedPunchId] = useState<string | null>(null);
    const [selectedNestPartId, setSelectedNestPartId] = useState<string | null>(null);

    const [optimizedOperations, setOptimizedOperations] = useState<PunchOp[] | null>(null);
    const sim = useSimulationState(optimizedOperations);
    const modals = useAppModals();

    const [manualPunchMode, setManualPunchMode] = useState<ManualPunchMode>(ManualPunchMode.Punch);
    const [selectedToolId, setSelectedToolId] = useState<string | null>(null);
    const [punchOrientation, setPunchOrientation] = useState(0);
    const [snapMode, setSnapMode] = useState<SnapMode>(SnapMode.Vertex);
    const [punchOffset, setPunchOffset] = useState<number>(0);
    const [nibbleSettings, setNibbleSettings] = useState<NibbleSettings>({ extensionStart: 0, extensionEnd: 0, minOverlap: 1, hitPointMode: 'offset', toolPosition: 'long' });
    const [destructSettings, setDestructSettings] = useState<DestructSettings>({ overlap: 0.7, scallop: 0.25, notchExpansion: 0.25 });

    const [teachMode, setTeachMode] = useState(false);
    const [selectedSegmentIds, setSelectedSegmentIds] = useState<number[]>([]);
    const [selectedTeachPunchIds, setSelectedTeachPunchIds] = useState<string[]>([]);

    const [generatedGCode, setGeneratedGCode] = useState('');
    const [isNestingProcessing, setIsNestingProcessing] = useState(false);
    const [nestingProgress, setNestingProgress] = useState(0);
    const [nestingStatus, setNestingStatus] = useState('');
    const [toasts, setToasts] = useState<ToastMessage[]>([]);

    const activePartProcessedGeometry = useMemo(() => activePart ? getGeometryFromEntities(activePart) : null, [activePart]);
    const activeNest = nests.find(n => n.id === activeNestId) || null;
    const currentNestSheet = activeNest?.sheets[activeSheetIndex] || null;
    const selectedTool = tools.find(t => t.id === selectedToolId) || null;

    const addToast = (message: string, type: ToastMessage['type']) => setToasts(prev => [...prev, { id: generateId(), message, type }]);
    const removeToast = (id: string) => setToasts(prev => prev.filter(t => t.id !== id));

    const { confirmationState, confirm, closeConfirmation } = useConfirmation();
    const { handleFileUpload } = useFileImport({ tools, setMode, setActivePart, addToast });

    const addPunchesWithCollisionCheck = (punchesData: Omit<PlacedTool, 'id'>[]) => {
        if (!activePart) return;
        const newPunches = punchesData.map(p => ({ ...p, id: generateId() }));
        setActivePart({ ...activePart, punches: [...activePart.punches, ...newPunches] });
    };

    const { handleCanvasClick: handleManualPunchClick, punchCreationStep, punchCreationPoints } = useManualPunch({
        activePart, activePartProcessedGeometry, selectedTool, manualPunchMode, punchOrientation, punchOffset, snapMode, nibbleSettings, destructSettings, onAddPunches: addPunchesWithCollisionCheck, setSelectedPunchId
    });

    const handleRunOptimization = (finalSettings: OptimizerSettings) => {
        if (!currentNestSheet) return;
        setOptimizerSettings(finalSettings);
        modals.setShowOptimizerModal(false);
        const ops = calculateOptimizedPath(currentNestSheet, parts, tools, finalSettings);
        setOptimizedOperations(ops);
        if (modals.isGeneratingGCode) {
            const code = generateGCode(currentNestSheet, parts, tools, 'Program.nc', machineSettings, finalSettings, activeNest?.settings.clampPositions || [], activeSheetIndex + 1, ops);
            setGeneratedGCode(code);
            modals.setShowGCodeModal(true);
        }
    };

    const handleCanvasClick = (rawPoint: Point) => {
        if (mode === AppMode.Nesting || !activePart) return;
        const point = { x: rawPoint.x, y: -rawPoint.y };
        if (teachMode) {
             const closestSeg = findClosestSegment(point, activePartProcessedGeometry);
             if (closestSeg) {
                 const idx = activePartProcessedGeometry?.segments.findIndex(s => Math.abs(s.p1.x - closestSeg.p1.x) < 0.001 && Math.abs(s.p1.y - closestSeg.p1.y) < 0.001) ?? -1;
                 if (idx !== -1) setSelectedSegmentIds(prev => prev.includes(idx) ? prev.filter(i => i !== idx) : [...prev, idx]);
             }
             return;
        }
        handleManualPunchClick(rawPoint);
    };

    const { svgRef, viewBox, setViewBox, isDragging, getPointFromEvent, panZoomHandlers } = usePanAndZoom({ x: 0, y: 0, width: 100, height: 100 }, { onClick: handleCanvasClick });

    const handleRunNesting = async () => {
        if(!activeNest || activeNest.scheduledParts.length===0) return;
        setIsNestingProcessing(true);
        try {
            for await (const update of nestingGenerator(activeNest.scheduledParts, parts, tools, activeNest.settings)) {
                setNests(prev => prev.map(n => n.id === activeNestId ? { ...n, sheets: update.sheets } : n));
                setNestingProgress(update.progress);
                setNestingStatus(update.status);
            }
        } catch(e:any) { addToast("Ошибка: " + e.message, "error"); }
        finally { setIsNestingProcessing(false); }
    };

    return (
        <div className="flex flex-col h-full relative">
            <Header mode={mode} setMode={setMode} onGenerateGCode={() => modals.openOptimizer(true)} onOptimizePath={() => modals.openOptimizer(false)} onOpenTurretConfig={() => setMode(AppMode.TurretSetup)} />
            <div className="flex flex-1 overflow-hidden">
                {(mode === AppMode.PartEditor || mode === AppMode.Nesting) ? (
                    <>
                        <Sidebar 
                            mode={mode} parts={parts} activePart={activePart} activePartId={activePart?.id || null} setActivePartId={() => {}} onDeletePart={id => setParts(p => p.filter(x => x.id !== id))} tools={tools} activeNest={activeNest} activeSheetIndex={activeSheetIndex} setActiveSheetIndex={setActiveSheetIndex} onFileUpload={handleFileUpload} manualPunchMode={manualPunchMode} setManualPunchMode={setManualPunchMode} selectedToolId={selectedToolId} setSelectedToolId={setSelectedToolId} selectedPunchId={selectedPunchId} setSelectedPunchId={setSelectedPunchId} onDeletePunch={id => setActivePart(p => p ? {...p, punches: p.punches.filter(x => !(Array.isArray(id)?id:[id]).includes(x.id))} : null)} onUpdatePunch={(id, u) => setActivePart(p => p ? {...p, punches: p.punches.map(x => x.id === id ? {...x, ...u} : x)} : null)} onClearAllPunches={() => setActivePart(p => p ? {...p, punches: []} : null)} punchOrientation={punchOrientation} setPunchOrientation={setPunchOrientation} onCyclePunchOrientation={() => setPunchOrientation((punchOrientation+90)%360)} snapMode={snapMode} setSnapMode={setSnapMode} punchOffset={punchOffset} setPunchOffset={setPunchOffset} onUpdateNestingSettings={(s, sp) => setNests(prev => prev.map(n => n.id === activeNestId ? { ...n, settings: s, scheduledParts: sp } : n))} onUpdateNestMetadata={m => setNests(prev => prev.map(n => n.id === activeNestId ? { ...n, ...m } : n))} nibbleSettings={nibbleSettings} setNibbleSettings={setNibbleSettings} destructSettings={destructSettings} setDestructSettings={setDestructSettings} onOpenTurretView={() => setMode(AppMode.TurretSetup)} onSavePartAsScript={() => {}} onSavePartAsStatic={() => {}} onUpdateActivePart={u => setActivePart(p => p ? {...p, ...u} : null)} onClosePart={() => setActivePart(null)} teachMode={teachMode} setTeachMode={v => setTeachMode(v)} onSaveTeachCycle={() => modals.setShowTeachSaveModal(true)} teachCycles={teachCycles} onDeleteTeachCycle={id => setTeachCycles(c => c.filter(x => x.id !== id))} onRunNesting={handleRunNesting} isNestingProcessing={isNestingProcessing} nestingProgress={nestingProgress} nestingStatus={nestingStatus} onClearNest={() => setNests(p => p.map(n => n.id === activeNestId ? {...n, sheets: []} : n))} selectedNestPartId={selectedNestPartId}
                        />
                        <CanvasArea mode={mode} activePart={activePart} processedGeometry={activePartProcessedGeometry} activeNest={activeNest} currentNestSheet={currentNestSheet} tools={tools} parts={parts} svgRef={svgRef} viewBox={viewBox} setViewBox={setViewBox} isDragging={isDragging} getPointFromEvent={getPointFromEvent} panZoomHandlers={panZoomHandlers} onOpenAutoPunchSettings={() => modals.setShowAutoPunchSettingsModal(true)} punchCreationStep={punchCreationStep} punchCreationPoints={punchCreationPoints} manualPunchMode={manualPunchMode} selectedToolId={selectedToolId} selectedPunchId={selectedPunchId} onSelectPunch={setSelectedPunchId} placementReference={PlacementReference.Edge} placementSide={PlacementSide.Outside} punchOrientation={punchOrientation} snapMode={snapMode} punchOffset={punchOffset} nibbleSettings={nibbleSettings} teachMode={teachMode} selectedSegmentIds={selectedSegmentIds} selectedTeachPunchIds={selectedTeachPunchIds} onTeachBulkSelect={(s, p, a) => { setSelectedSegmentIds(s); setSelectedTeachPunchIds(p); }} selectedNestPartId={selectedNestPartId} onSelectNestPart={setSelectedNestPartId} onMoveNestPart={() => {}} optimizedOperations={optimizedOperations} simulationStep={sim.simulationStep} />
                        <RightPanel tools={tools} selectedToolId={selectedToolId} setSelectedToolId={setSelectedToolId} onOpenTurretView={() => setMode(AppMode.TurretSetup)} isNestingMode={mode === AppMode.Nesting} activeNest={activeNest} activeSheetIndex={activeSheetIndex} setActiveSheetIndex={setActiveSheetIndex} allParts={parts} simulationStep={sim.simulationStep} totalSimulationSteps={optimizedOperations?.length || 0} isSimulating={sim.isSimulating} simulationSpeed={sim.simulationSpeed} onToggleSimulation={sim.toggleSimulation} onStopSimulation={sim.stopSimulation} onStepChange={sim.stepSimulation} onSpeedChange={sim.setSimulationSpeed} optimizedOperations={optimizedOperations} />
                    </>
                ) : (
                    mode === AppMode.PartLibrary ? (
                        <PartLibraryView parts={parts} tools={tools} onLoadPart={p => { setActivePart(p); setMode(AppMode.PartEditor); }} onDeletePart={id => setParts(p => p.filter(x => x.id !== id))} onUpdatePart={p => setParts(prev => prev.map(x => x.id === p.id ? p : x))} />
                    ) : mode === AppMode.ScriptLibrary ? (
                        <ScriptLibraryView scripts={scripts} tools={tools} parts={parts} onSaveScript={s => setScripts(prev => prev.map(x => x.id === s.id ? s : x))} onDeleteScript={id => setScripts(s => s.filter(x => x.id !== id))} onCreatePart={p => setParts(prev => [...prev, p])} onBatchProcess={(p, s) => {}} />
                    ) : mode === AppMode.ToolLibrary ? (
                        <ToolLibraryView tools={tools} onSaveTool={t => setTools(prev => prev.find(x => x.id === t.id) ? prev.map(x => x.id === t.id ? t : x) : [...prev, t])} onDeleteTool={id => setTools(t => t.filter(x => x.id !== id))} />
                    ) : mode === AppMode.TurretSetup ? (
                        <TurretSetupView tools={tools} setTools={setTools} layouts={turretLayouts} setLayouts={setTurretLayouts} />
                    ) : mode === AppMode.MachineSetup ? (
                        <MachineSetupView settings={machineSettings} onUpdate={setMachineSettings} />
                    ) : null
                )}
            </div>
            {modals.showAutoPunchSettingsModal && activePart && <AutoPunchSettingsModal onClose={() => modals.setShowAutoPunchSettingsModal(false)} onApply={s => { const p = generateContourPunches(activePart.geometry, tools, s, turretLayouts, teachCycles); addPunchesWithCollisionCheck(p); modals.setShowAutoPunchSettingsModal(false); }} turretLayouts={turretLayouts} />}
            {modals.showOptimizerModal && <OptimizerSettingsModal initialSettings={optimizerSettings} onClose={() => modals.setShowOptimizerModal(false)} onGenerate={handleRunOptimization} />}
            {modals.showGCodeModal && <GCodeModal gcode={generatedGCode} onClose={() => modals.setShowGCodeModal(false)} onDownload={() => {}} sheet={currentNestSheet || undefined} parts={parts} tools={tools} />}
            <ToastContainer toasts={toasts} removeToast={removeToast} />
            <ConfirmationModal state={confirmationState} onCancel={closeConfirmation} />
        </div>
    );
};
export default App;

