// Helper for intersection check needed by detector
const segmentIntersectsGeometry = (p1: Point, p2: Point, entities: DxfEntity[]): boolean => {
    const checkLine = (a: Point, b: Point) => {
        const det = (p2.x - p1.x) * (b.y - a.y) - (p2.y - p1.y) * (b.x - a.x);
        if (det === 0) return false;
        const denominator = ((p2.x - p1.x) * (b.y - a.y)) - ((p2.y - p1.y) * (b.x - a.x));
        if (denominator === 0) return false;
        const numerator1 = ((p1.y - a.y) * (b.x - a.x)) - ((p1.x - a.x) * (b.y - a.y));
        const r = numerator1 / denominator;
        const s = (((p1.y - a.y) * (p2.x - p1.x)) - ((p1.x - a.x) * (p2.y - p1.y))) / denominator;
        return (r > 0.01 && r < 0.99) && (s > 0.01 && s < 0.99);
    };

    for (const entity of entities) {
        if (entity.type === 'LINE') {
            if (checkLine(entity.start, entity.end)) return true;
        } else if (entity.type === 'LWPOLYLINE') {
            const v = entity.vertices;
            for (let i = 0; i < v.length - 1; i++) if (checkLine(v[i], v[i+1])) return true;
            if (entity.closed && v.length > 1) if (checkLine(v[v.length-1], v[0])) return true;
        }
    }
    return false;
};

export const detectPartProfile = (geometry: PartGeometry): PartProfile => {
    const { bbox, entities, height } = geometry;
    const width = bbox.maxX - bbox.minX;
    if (entities.length === 0) return { type: 'flat', orientation: 'vertical', dims: { a: width, b: 0, c: 0 } };

    const toSvgY = (rawY: number) => rawY - bbox.minY;
    const toSvgX = (rawX: number) => rawX - bbox.minX;
    const MIN_DEPTH = 0.5, MAX_DEPTH = 50.0;
    const topZone = { min: height - MAX_DEPTH, max: height - MIN_DEPTH };
    const bottomZone = { min: MIN_DEPTH, max: MAX_DEPTH };
    const leftZone = { min: MIN_DEPTH, max: MAX_DEPTH };
    const rightZone = { min: width - MAX_DEPTH, max: width - MIN_DEPTH };

    const verticalBendCandidates: number[] = [];
    const horizontalBendCandidates: number[] = [];

    const isVisibleFromEdge = (pRaw: Point, edge: 'top'|'bottom'|'left'|'right'): boolean => {
        let target = { ...pRaw };
        if (edge === 'top') target.y = bbox.maxY + 1;
        else if (edge === 'bottom') target.y = bbox.minY - 1;
        else if (edge === 'left') target.x = bbox.minX - 1;
        else if (edge === 'right') target.x = bbox.maxX + 1;
        return !segmentIntersectsGeometry(pRaw, target, entities);
    };

    const checkPoint = (rawP: Point) => {
        const svgX = toSvgX(rawP.x), svgY = toSvgY(rawP.y);
        if (svgY > topZone.min && svgY < topZone.max && isVisibleFromEdge(rawP, 'top')) verticalBendCandidates.push(svgX);
        if (svgY > bottomZone.min && svgY < bottomZone.max && isVisibleFromEdge(rawP, 'bottom')) verticalBendCandidates.push(svgX);
        if (svgX > leftZone.min && svgX < leftZone.max && isVisibleFromEdge(rawP, 'left')) horizontalBendCandidates.push(svgY);
        if (svgX > rightZone.min && svgX < rightZone.max && isVisibleFromEdge(rawP, 'right')) horizontalBendCandidates.push(svgY);
    };

    entities.forEach(e => {
        if (e.type === 'ARC') checkPoint(e.center);
        else if (e.type === 'LWPOLYLINE') e.vertices.forEach(v => checkPoint(v));
    });

    const clusterPoints = (coords: number[], rangeMax: number): number[] => {
        if (coords.length === 0) return [];
        coords.sort((a, b) => a - b);
        const clusters: number[] = [];
        let currentCluster: number[] = [coords[0]];
        const TOL = 20.0;
        for (let i = 1; i < coords.length; i++) {
            if (coords[i] - coords[i-1] < TOL) currentCluster.push(coords[i]);
            else { clusters.push(currentCluster.reduce((a,b)=>a+b,0) / currentCluster.length); currentCluster = [coords[i]]; }
        }
        if (currentCluster.length > 0) clusters.push(currentCluster.reduce((a,b)=>a+b,0) / currentCluster.length);
        const margin = Math.min(rangeMax * 0.1, 50.0);
        return clusters.filter(val => val > margin && val < (rangeMax - margin));
    };

    const vBends = clusterPoints(verticalBendCandidates, width);
    if (vBends.length > 0) {
        if (vBends.length === 1) return { type: 'L', orientation: 'vertical', dims: { a: parseFloat(vBends[0].toFixed(2)), b: parseFloat((width - vBends[0]).toFixed(2)), c: 0 } };
        return { type: 'U', orientation: 'vertical', dims: { a: parseFloat(vBends[0].toFixed(2)), b: parseFloat((vBends[1] - vBends[0]).toFixed(2)), c: parseFloat((width - vBends[1]).toFixed(2)) } };
    }
    const hBends = clusterPoints(horizontalBendCandidates, height);
    if (hBends.length > 0) {
        if (hBends.length === 1) return { type: 'L', orientation: 'horizontal', dims: { a: parseFloat(hBends[0].toFixed(2)), b: parseFloat((height - hBends[0]).toFixed(2)), c: 0 } };
        return { type: 'U', orientation: 'horizontal', dims: { a: parseFloat(hBends[0].toFixed(2)), b: parseFloat((hBends[1] - hBends[0]).toFixed(2)), c: parseFloat((height - hBends[1]).toFixed(2)) } };
    }
    return { type: 'flat', orientation: 'vertical', dims: { a: width, b: 0, c: 0 } };
};

