export interface ProcessedGeometry { 
    vertices: Point[]; 
    segments: Segment[]; 
    bbox: PartGeometry['bbox'];
    holeCenters: { point: Point, rotation?: number }[];
};

export type Segment = { 
    p1: Point; 
    p2: Point; 
    type: 'line' | 'arc';
    radius?: number;
    center?: Point;
    originalEntity?: any; 
};

/**
 * Calculates physical extents and origin offset for a part at a specific rotation.
 */
export const getRotatedExtents = (part: Part, rotation: number, tools: Tool[]) => {
    const rad = (rotation * Math.PI) / 180;
    const cos = Math.cos(rad);
    const sin = Math.sin(rad);
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;

    const basePoints: Point[] = [{ x: 0, y: 0 }, { x: part.geometry.width, y: 0 }, { x: part.geometry.width, y: part.geometry.height }, { x: 0, y: part.geometry.height }];
    basePoints.forEach(p => {
        const rx = p.x * cos - p.y * sin, ry = p.x * sin + p.y * cos;
        if (rx < minX) minX = rx; if (rx > maxX) maxX = rx;
        if (ry < minY) minY = ry; if (ry > maxY) maxY = ry;
    });

    part.punches.forEach(p => {
        const tool = tools.find(t => t.id === p.toolId);
        if (!tool) return;
        const punchRad = (p.rotation + rotation) * Math.PI / 180;
        const tCos = Math.abs(Math.cos(punchRad)), tSin = Math.abs(Math.sin(punchRad));
        let tW = tool.width, tH = tool.shape === ToolShape.Circle ? tool.width : tool.height;
        const effW = tW * tCos + tH * tSin, effH = tW * tSin + tH * tCos;
        const rx = p.x * cos - p.y * sin, ry = p.x * sin + p.y * cos;
        if (rx - effW/2 < minX) minX = rx - effW/2; if (rx + effW/2 > maxX) maxX = rx + effW/2;
        if (ry - effH/2 < minY) minY = ry - effH/2; if (ry + effH/2 > maxY) maxY = ry + effH/2;
    });

    return { width: maxX - minX, height: maxY - minY, ox: -minX, oy: -minY };
};

export const isPointInsideContour = (point: Point, partGeometry: PartGeometry): boolean => {
    const { bbox, entities } = partGeometry;
    if (!bbox || !entities || point.x < bbox.minX || point.x > bbox.maxX || point.y < bbox.minY || point.y > bbox.maxY) return false;
    let intersections = 0;
    entities.forEach(entity => {
        if (entity.type === 'LWPOLYLINE') {
            for (let i = 0; i < entity.vertices.length; i++) {
                const p1 = entity.vertices[i], p2 = entity.vertices[(i + 1) % entity.vertices.length];
                if (entity.closed || i < entity.vertices.length - 1) if (rayIntersects(point, p1, p2)) intersections++;
            }
        } else if (entity.type === 'LINE') { if (rayIntersects(point, entity.start, entity.end)) intersections++; }
    });
    return intersections % 2 !== 0;
};

const rayIntersects = (p: Point, a: Point, b: Point): boolean => (a.y > p.y) !== (b.y > p.y) && p.x < a.x + (p.y - a.y) * (b.x - a.x) / (b.y - a.y);

export const doPartsIntersect = (partA: Part, posA: Point, rotA: number, partB: Part, posB: Point, rotB: number, margin: number = 0): boolean => {
    const getSegs = (p: Part, pos: Point, rot: number) => {
        const rad = rot * Math.PI / 180, cos = Math.cos(rad), sin = Math.sin(rad);
        const pg = getGeometryFromEntities(p);
        return pg ? pg.segments.map(s => ({ p1: { x: pos.x + (s.p1.x * cos - s.p1.y * sin), y: pos.y + (s.p1.x * sin + s.p1.y * cos) }, p2: { x: pos.x + (s.p2.x * cos - s.p2.y * sin), y: pos.y + (s.p2.x * sin + s.p2.y * cos) } })) : [];
    };
    const segsA = getSegs(partA, posA, rotA), segsB = getSegs(partB, posB, rotB);
    for (const sA of segsA) for (const sB of segsB) if (lineIntersect(sA.p1, sA.p2, sB.p1, sB.p2)) return true;
    return false;
};

const lineIntersect = (p1: Point, p2: Point, p3: Point, p4: Point): boolean => {
    const det = (p2.x - p1.x) * (p4.y - p3.y) - (p2.y - p1.y) * (p4.x - p3.x);
    if (det === 0) return false;
    const l = ((p4.y - p3.y) * (p4.x - p1.x) + (p3.x - p4.x) * (p4.y - p1.y)) / det;
    const g = ((p1.y - p2.y) * (p4.x - p1.x) + (p2.x - p1.x) * (p4.y - p1.y)) / det;
    return l > 0 && l < 1 && g > 0 && g < 1;
};

export const isPointInRectangle = (point: Point, rectX: number, rectY: number, width: number, height: number, rotation: number): boolean => {
    const dx = point.x - rectX, dy = point.y - rectY, rad = -rotation * (Math.PI / 180);
    const lx = dx * Math.cos(rad) - dy * Math.sin(rad), ly = dx * Math.sin(rad) + dy * Math.cos(rad);
    return lx >= 0 && lx <= width && ly >= 0 && ly <= height;
};

export const getToolCorners = (tool: Tool, x: number, y: number, rotation: number): Point[] => {
    const w = tool.width, h = tool.shape === ToolShape.Circle ? tool.width : tool.height, rad = rotation * (Math.PI / 180), cos = Math.cos(rad), sin = Math.sin(rad);
    return [{x:-w/2,y:-h/2},{x:w/2,y:-h/2},{x:w/2,y:h/2},{x:-w/2,y:h/2}].map(p => ({ x: x + (p.x * cos - p.y * sin), y: y + (p.x * sin + p.y * cos) }));
};

export const isToolGouging = (tool: Tool, x: number, y: number, rotation: number, geometry: PartGeometry, bbox: PartGeometry['bbox'], currentSegment: Segment, allSegments?: Segment[]): boolean => {
    const corners = getToolCorners(tool, x, y, rotation);
    for (const corner of corners) {
        if (isPointInsideContour({ x: corner.x + bbox.minX, y: corner.y + bbox.minY }, geometry)) {
            let dist = Infinity;
            if (currentSegment.type === 'line') {
                const {p1, p2} = currentSegment, l2 = (p2.x-p1.x)**2+(p2.y-p1.y)**2;
                if (l2 === 0) dist = Math.sqrt((corner.x-p1.x)**2+(corner.y-p1.y)**2);
                else {
                    let t = Math.max(0, Math.min(1, ((corner.x-p1.x)*(p2.x-p1.x)+(corner.y-p1.y)*(p2.y-p1.y))/l2));
                    dist = Math.sqrt((corner.x-(p1.x+t*(p2.x-p1.x)))**2+(corner.y-(p1.y+t*(p2.y-p1.y)))**2);
                }
            }
            if (dist > 0.5) return true;
        }
    }
    return false;
};

export const getGeometryFromEntities = (part: Part): ProcessedGeometry | null => {
    const { entities, bbox } = part.geometry;
    if (!entities || !bbox) return null;
    const vertices: Point[] = [], segments: Segment[] = [];
    const norm = (p: Point) => ({ x: p.x - bbox.minX, y: p.y - bbox.minY });
    entities.forEach(e => {
        if (e.type === 'LINE') { const p1 = norm(e.start), p2 = norm(e.end); vertices.push(p1, p2); segments.push({ p1, p2, type: 'line', originalEntity: e }); }
        else if (e.type === 'LWPOLYLINE') {
            const pts = e.vertices.map(v => norm(v));
            for(let i=0; i<pts.length-1; i++) segments.push({ p1: pts[i], p2: pts[i+1], type: 'line', originalEntity: e });
            if (e.closed) segments.push({ p1: pts[pts.length-1], p2: pts[0], type: 'line', originalEntity: e });
            vertices.push(...pts);
        }
    });
    return { vertices, segments, bbox, holeCenters: [] };
};

