export class ComplexPacker implements INestingPacker {
    private placed: { item: PackerItem; result: PlacedResult }[] = [];

    constructor(
        public readonly sheetW: number,
        public readonly sheetH: number,
        private readonly spacingX: number,
        private readonly spacingY: number,
        private readonly parts: Part[],
        private readonly tools: Tool[]
    ) {}

    async findPosition(item: PackerItem): Promise<PlacedResult | null> {
        const partDef = this.parts.find(p => p.id === item.partId);
        if (!partDef) return null;
        const step = 10; 
        for (let x = 0; x <= this.sheetW - step; x += step) {
            if (x % 100 === 0) await new Promise(r => setTimeout(r, 0));
            for (const rot of item.allowedRotations) {
                const ext = getRotatedExtents(partDef, rot, this.tools);
                if (x + ext.width > this.sheetW) continue;
                for (let y = 0; y <= this.sheetH - ext.height; y += step) {
                    const cOrigin: Point = { x: x + ext.ox, y: y + ext.oy };
                    let collision = false;
                    for (const p of this.placed) {
                        const pDef = this.parts.find(px => px.id === p.item.partId);
                        if (pDef && doPartsIntersect(partDef, cOrigin, rot, pDef, { x: p.result.x + p.result.ox, y: p.result.y + p.result.oy }, p.result.rotation, Math.max(this.spacingX, this.spacingY))) {
                            collision = true; break;
                        }
                    }
                    if (!collision) return { x, y, rotation: rot, ox: ext.ox, oy: ext.oy, width: ext.width, height: ext.height };
                }
            }
        }
        return null;
    }

    placeItem(item: PackerItem, result: PlacedResult) { this.placed.push({ item, result }); }
    getPlacedItems() { return this.placed; }
}

