export interface NestingProgressUpdate { sheets: NestResultSheet[]; progress: number; status: string; }

export async function* nestingGenerator(scheduledParts: ScheduledPart[], allParts: Part[], tools: Tool[], settings: NestingSettings): AsyncGenerator<NestingProgressUpdate> {
    const items: PackerItem[] = [];
    for (const sp of scheduledParts) {
        const part = allParts.find(p => p.id === sp.partId);
        if (!part) continue;
        const ext = getRotatedExtents(part, 0, tools);
        const allowed = [0, ...(sp.nesting.allow0_180 ? [180] : []), ...(sp.nesting.allow90_270 ? [90, 270] : [])];
        for (let i = 0; i < sp.quantity; i++) {
            items.push({ uid: generateId(), partId: sp.partId, name: part.name, width: ext.width, height: ext.height, offsetX: ext.ox, offsetY: ext.oy, allowedRotations: allowed, hasCommonLine: sp.nesting.commonLine, area: ext.width * ext.height, aspectRatio: ext.width / ext.height });
        }
    }
    items.sort((a, b) => b.area - a.area);
    const total = items.length; let packedCount = 0, completed: NestResultSheet[] = [], remaining = [...items];

    while (remaining.length > 0) {
        const stock = settings.availableSheets.find(s => s.useInNesting && s.quantity > 0);
        if (!stock) break;
        const effW = stock.width - settings.sheetMarginLeft - settings.sheetMarginRight, effH = stock.height - settings.sheetMarginTop - settings.sheetMarginBottom;
        const packer: INestingPacker = settings.nestAsRectangle 
            ? new RectanglePacker(effW, effH, settings.partSpacingX, settings.partSpacingY, allParts, tools)
            : new ComplexPacker(effW, effH, settings.partSpacingX, settings.partSpacingY, allParts, tools);

        let onSheet: string[] = [];
        for (const item of remaining) {
            const pos = await packer.findPosition(item);
            if (pos) { packer.placeItem(item, pos); onSheet.push(item.uid); packedCount++; yield { sheets: [...completed], progress: (packedCount / total) * 100, status: `Размещение: ${item.name}` }; }
        }
        if (onSheet.length === 0) { remaining.shift(); continue; }
        remaining = remaining.filter(it => !onSheet.includes(it.uid));
        const placed = packer.getPlacedItems(), usedArea = placed.reduce((s, p) => s + p.item.area, 0), totalArea = stock.width * stock.height;
        completed.push({ id: generateId(), sheetName: `Sheet ${completed.length + 1}`, stockSheetId: stock.id, width: stock.width, height: stock.height, material: stock.material, thickness: stock.thickness, usedArea: (usedArea / totalArea) * 100, scrapPercentage: 100 - (usedArea / totalArea) * 100, partCount: placed.length, quantity: 1, placedParts: placed.map(p => ({ id: generateId(), partId: p.item.partId, x: p.result.x + settings.sheetMarginLeft + p.result.ox, y: p.result.y + settings.sheetMarginBottom + p.result.oy, rotation: p.result.rotation })) });
        yield { sheets: [...completed], progress: (packedCount / total) * 100, status: `Лист #${completed.length} готов` };
    }
}

