export const buildVertexMap = (segments: Segment[]) => {
    const map = new Map<string, { point: Point, indices: number[] }>();
    segments.forEach((s, i) => {
        [s.p1, s.p2].forEach(p => {
            const k = getPointKey(p);
            if (!map.has(k)) map.set(k, { point: p, indices: [] });
            map.get(k)!.indices.push(i);
        });
    });
    return map;
};

export const calculateMicroJoints = (processed: any, settings: AutoPunchSettings) => {
    const joints = new Set<string>();
    const outerIndices = getOuterLoopIndices(processed.segments);
    if (!settings.microJointsEnabled || outerIndices.size === 0) return joints;

    const { minX, minY, maxX, maxY } = processed.bbox;
    if (settings.microJointType === 'auto') {
        const corners = [{ x: minX, y: maxY }, { x: maxX, y: maxY }, { x: maxX, y: minY }, { x: minX, y: minY }];
        corners.forEach(target => {
            let bestKey = null, bestScore = -Infinity;
            buildVertexMap(processed.segments).forEach((data, key) => {
                const dist = Math.sqrt((data.point.x - target.x)**2 + (data.point.y - target.y)**2);
                const score = -dist; // Simplistic: closest to sheet corners
                if (score > bestScore) { bestScore = score; bestKey = key; }
            });
            if (bestKey) joints.add(bestKey);
        });
    }
    return joints;
};

