export const generateContourPunches = (
    geometry: PartGeometry,
    tools: Tool[],
    settings: AutoPunchSettings,
    turretLayouts: TurretLayout[],
    teachCycles: TeachCycle[]
): Omit<PlacedTool, 'id'>[] => {
    const processed = getGeometryFromEntities({ geometry } as Part); 
    if (!processed) return [];

    const punches: Omit<PlacedTool, 'id'>[] = [];
    const covered = new Set<number>();
    const jointVertices = calculateMicroJoints(processed, settings);

    // 1. Shapes and Loops
    let availableTools = tools;
    if (settings.toolSourceType === 'turret' && settings.turretLayoutId) {
        const layout = turretLayouts.find(l => l.id === settings.turretLayoutId);
        if (layout) availableTools = layout.toolsSnapshot.filter(t => !!t.stationNumber);
    }

    punches.push(...detectAndPunchShapes(geometry, processed, availableTools, settings, covered));
    punches.push(...detectLoopTools(processed, availableTools, settings, covered));

    // 2. Segments
    processed.segments.forEach((seg, idx) => {
        if (covered.has(idx)) return;
        if (seg.type === 'line') punches.push(...processLine(seg, geometry, availableTools, settings, jointVertices));
        else if (seg.type === 'arc') punches.push(...processArc(seg, geometry, availableTools, settings));
    });

    return punches;
};

