/**
 * Extracts vertices from a tool's path definition or generates them for standard shapes.
 * Vertices are centered around (0,0).
 */
const getToolVertices = (tool: Tool): Point[] => {
    const w = tool.width;
    const h = tool.height;

    if (tool.shape === ToolShape.Special && tool.customPath) {
        // Parse SVG path "M x y L x y ..."
        // customPath is typically in 0..W, 0..H coordinates based on ToolDisplay logic (translated by -w/2, -h/2)
        // We will parse it and apply the center shift (-w/2, -h/2).

        const vertices: Point[] = [];
        const commands: string[] = tool.customPath.match(/([a-zA-Z])([^a-zA-Z]*)/g) || [];
        const shiftX = -w / 2;
        const shiftY = -h / 2;

        let startX = 0;
        let startY = 0;

        commands.forEach(cmd => {
            const type = cmd[0].toUpperCase();
            const args = cmd.slice(1).trim().split(/[\s,]+/).map(parseFloat);

            if (type === 'M') {
                const x = args[0] + shiftX;
                const y = args[1] + shiftY;
                vertices.push({x, y});
                startX = x;
                startY = y;
            } else if (type === 'L') {
                const x = args[0] + shiftX;
                const y = args[1] + shiftY;
                vertices.push({x, y});
            } else if (type === 'A') {
                // A rx ry rot large sweep x y
                // We approximate Arc by its endpoint for placement logic
                // (Assuming user aligns to chords/tangents defined by endpoints)
                const x = args[5] + shiftX;
                const y = args[6] + shiftY;
                vertices.push({x, y});
            } else if (type === 'Z') {
                 // Close path: usually connects back to M.
                 // We don't explicitly need to push start point again unless logic requires closed loop segments
            }
        });

        return vertices;
    } 

    // Standard Shapes (Rect/Square/Oblong as Box)
    // Vertices order: Top-Left, Top-Right, Bottom-Right, Bottom-Left
    // This winding ensures the first segment (TL -> TR) has angle 0 (Horizontal, dx>0)
    // and corresponds to the Top Edge (y = -h/2).
    // This matches the winding of typical DXF-imported special tools, ensuring 
    // consistent "Active Face" detection and Inside/Outside placement logic.
    return [
        { x: -w/2, y: -h/2 },
        { x: w/2, y: -h/2 },
        { x: w/2, y: h/2 },
        { x: -w/2, y: h/2 }
    ];
};

/**
 * Calculates the final position and rotation for a tool to align with a contour edge.
 * Supports arbitrary tool shapes by analyzing the active face in the rotated frame.
 */
export const calculateEdgePlacement = (
    snapPoint: Point,
    snapAngle: number,
    tool: Tool,
    toolOrientation: number,
    offset: number = 0,
    snapTarget: SnapTarget,
    wasNormalized: boolean,
    placementSide: PlacementSide = PlacementSide.Outside
): { x: number, y: number, rotation: number } => {

    // 1. Calculate Final World Rotation
    // The tool is rotated by `toolOrientation` to align its active face to "Horizontal (0 deg)".
    // Then it is rotated by `snapAngle` to align that face with the contour.
    const finalRotation = snapAngle + toolOrientation;

    // 2. Get Tool Geometry
    const vertices = getToolVertices(tool);
    if (vertices.length === 0) return { x: snapPoint.x, y: snapPoint.y, rotation: finalRotation };

    // 3. Rotate vertices by `toolOrientation` to find the Active Face.
    // In this local rotated frame, the Active Face is the one with angle ~0 degrees (Horizontal, Left->Right).
    const rad = (toolOrientation * Math.PI) / 180;
    const cos = Math.cos(rad);
    const sin = Math.sin(rad);

    const rotatedVertices = vertices.map(v => ({
        x: v.x * cos - v.y * sin,
        y: v.x * sin + v.y * cos
    }));

    // 4. Identify Active Face (Segment with Angle ~ 0)
    // We look for a segment (v[i] -> v[i+1]) where deltaY ~ 0 and deltaX > 0.
    let bestFaceY = 0;
    let bestFaceMinX = 0;
    let bestFaceMaxX = 0;
    let foundFace = false;

    // Treat vertices as a closed loop
    const count = rotatedVertices.length;
    for (let i = 0; i < count; i++) {
        const p1 = rotatedVertices[i];
        const p2 = rotatedVertices[(i + 1) % count];

        const dx = p2.x - p1.x;
        const dy = p2.y - p1.y;

        // Check for horizontal, positive X direction (Angle 0)
        // Tolerance for float errors
        if (Math.abs(dy) < 0.001 && dx > 0) {
            // Found a candidate face. 
            bestFaceY = p1.y; // p1.y should be approx p2.y
            bestFaceMinX = p1.x;
            bestFaceMaxX = p2.x;
            foundFace = true;
            break; 
        }
    }

    if (!foundFace) {
        // Fallback strategy: Find the vertex with Max Y (Bottom-most in SVG) -> Should match Top Face?
        // If we switched winding, Top Face is at y = -h/2 (Min Y).
        // Angle 0 face should be detected above.
        // If not found, rely on finding Min Y for Top Edge (consistent with new winding).
        let minY = Infinity;
        rotatedVertices.forEach(v => {
            if (v.y < minY) minY = v.y;
        });

        bestFaceY = minY;

        // Find extent at this Y
        const faceVerts = rotatedVertices.filter(v => Math.abs(v.y - minY) < 0.001);
        if (faceVerts.length >= 1) {
             const xs = faceVerts.map(v => v.x);
             bestFaceMinX = Math.min(...xs);
             bestFaceMaxX = Math.max(...xs);
        } else {
            bestFaceMinX = 0;
            bestFaceMaxX = 0;
        }
    }

    // 5. Determine Local Contact Point on the Active Face
    let localContactX = 0;
    switch(snapTarget) {
        case 'start': 
            localContactX = bestFaceMinX; 
            break;
        case 'end': 
            localContactX = bestFaceMaxX; 
            break;
        case 'middle':
        default:
            localContactX = (bestFaceMinX + bestFaceMaxX) / 2;
            break;
    }
    const localContactY = bestFaceY;

    // 6. Transform Local Contact Vector to World Space

    // Adjust Lateral Offset (Y) based on Placement Side
    // Inside (Material Side): Use Active Face as is (matches contour).
    // Outside (Scrap Side): Flip the Y offset to align the opposite side of the tool.
    // Note: We DO NOT flip X (Longitudinal), preserving direction along the line.
    const lateralOffset = placementSide === PlacementSide.Inside ? localContactY : -localContactY;

    const snapRad = (snapAngle * Math.PI) / 180;
    const snapCos = Math.cos(snapRad);
    const snapSin = Math.sin(snapRad);

    // Rotate the local contact vector (X, Y_adjusted) by the Snap Angle
    const worldContactVectorX = localContactX * snapCos - lateralOffset * snapSin;
    const worldContactVectorY = localContactX * snapSin + lateralOffset * snapCos;

    // 7. Calculate Tool Center
    // We always SUBTRACT the contact vector from the Snap Point.
    // This moves the tool such that its contact point coincides with the snap point.
    // Since we adjusted Lateral Offset above, this handles Inside/Outside placement correctly.
    const centerX = snapPoint.x - worldContactVectorX;
    const centerY = snapPoint.y - worldContactVectorY;

    // 8. Apply Parallel Offset
    // Offset is parallel to the contour tangent.
    const parOffsetX = offset * snapCos;
    const parOffsetY = offset * snapSin;

    const finalX = centerX + parOffsetX;
    const finalY = centerY + parOffsetY;

    // 9. Normalize Rotation
    let outputRotation = finalRotation % 360;
    if (outputRotation < 0) outputRotation += 360;

    return {
        x: finalX,
        y: finalY,
        rotation: outputRotation
    };
};

import { useState } from 'react';
import { Part, Tool, Point, ManualPunchMode, SnapMode, PlacementSide, PlacedTool, NibbleSettings, DestructSettings, ToolShape } from '../types';
import { ProcessedGeometry, findClosestSegment, findSnapPoint, isPointInsideContour } from '../services/geometry';
import { calculateEdgePlacement } from '../services/placement';
// FIXED: Import generateNibblePunches and generateDestructPunches from punchingGenerators instead of punching
import { generateNibblePunches, generateDestructPunches } from '../services/punchingGenerators';

interface UseManualPunchProps {
    activePart: Part | null;
    activePartProcessedGeometry: ProcessedGeometry | null;
    selectedTool: Tool | null;
    manualPunchMode: ManualPunchMode;
    punchOrientation: number;
    punchOffset: number;
    snapMode: SnapMode;
    nibbleSettings: NibbleSettings;
    destructSettings: DestructSettings;
    onAddPunches: (punches: Omit<PlacedTool, 'id'>[]) => void;
    setSelectedPunchId: (id: string | null) => void;
}

export const useManualPunch = ({
    activePart,
    activePartProcessedGeometry,
    selectedTool,
    manualPunchMode,
    punchOrientation,
    punchOffset,
    snapMode,
    nibbleSettings,
    destructSettings,
    onAddPunches,
    setSelectedPunchId
}: UseManualPunchProps) => {

    const [punchCreationStep, setPunchCreationStep] = useState(0);
    const [punchCreationPoints, setPunchCreationPoints] = useState<Point[]>([]);

    const handleCanvasClick = (rawPoint: Point) => {
        // Invert Y to match Model Coordinates (Cartesian Y-Up)
        const point = { x: rawPoint.x, y: -rawPoint.y };

        setSelectedPunchId(null);
        if (!selectedTool || !activePart) return;

        const snapResult = findSnapPoint(point, activePartProcessedGeometry, snapMode);
        const finalPoint = snapResult?.point ?? point;

        switch(manualPunchMode) {
            case ManualPunchMode.Punch: {
                if (snapMode === SnapMode.ShapeCenter) {
                    let rotation = punchOrientation;

                    // Smart Rotation: If feature dictates angle (forceRotation is hole angle, e.g., 90 for vertical oblong)
                    if (snapResult?.forceRotation !== undefined) {
                        const holeAngle = snapResult.forceRotation;

                        // Default Tool Orientation: usually 0 is Horizontal (W > H).
                        // If Tool is naturally W > H (Horizontal):
                        //   Target Vertical Hole (90): We need rotation 90.
                        //   Target Horizontal Hole (0): We need rotation 0.
                        // If Tool is naturally H > W (Vertical):
                        //   Target Vertical Hole (90): We need rotation 0 (stays vertical).
                        //   Target Horizontal Hole (0): We need rotation 90.

                        const isToolHorizontal = selectedTool.width >= selectedTool.height;

                        if (isToolHorizontal) {
                            rotation = holeAngle;
                        } else {
                            // Tool is naturally vertical.
                            // If hole is 0 (Horz), we need 90 to make vertical tool horizontal.
                            // If hole is 90 (Vert), we need 0 to keep vertical tool vertical.
                            rotation = (holeAngle + 90) % 360;
                        }
                    }
                    onAddPunches([{ toolId: selectedTool.id, x: finalPoint.x, y: finalPoint.y, rotation }]);
                    return;
                }

                const placementAngle = snapResult?.angle ?? 0;

                // Rigorous Outside Check: Calculate both Inside and Outside placements and pick the one truly in Scrap.
                // 1. Calculate Candidate A (Outside Param)
                const placementA = calculateEdgePlacement(
                    finalPoint, placementAngle, selectedTool, punchOrientation, punchOffset, 
                    snapResult?.snapTarget ?? 'middle', snapResult?.wasNormalized ?? false, PlacementSide.Outside
                );

                // 2. Calculate Candidate B (Inside Param)
                const placementB = calculateEdgePlacement(
                    finalPoint, placementAngle, selectedTool, punchOrientation, punchOffset, 
                    snapResult?.snapTarget ?? 'middle', snapResult?.wasNormalized ?? false, PlacementSide.Inside
                );

                let finalPlacement = placementA;

                if (activePartProcessedGeometry && activePart) {
                    const isInsideA = isPointInsideContour(placementA, activePart.geometry);
                    const isInsideB = isPointInsideContour(placementB, activePart.geometry);

                    // We want the tool to be in SCRAP (Outside of Contour).
                    // isPointInsideContour returns TRUE if in Material.
                    // So we want the one where isInside is FALSE.

                    if (!isInsideA && isInsideB) {
                        finalPlacement = placementA;
                    } else if (isInsideA && !isInsideB) {
                        finalPlacement = placementB;
                    } else {
                        // Fallback if both are outside or both inside: keep default Outside param (A)
                        finalPlacement = placementA;
                    }
                }

                onAddPunches([{ toolId: selectedTool.id, x: finalPlacement.x, y: finalPlacement.y, rotation: finalPlacement.rotation }]);
                break;
            }
            case ManualPunchMode.Nibble: {
                const closestSeg = findClosestSegment(point, activePartProcessedGeometry);
                if (closestSeg) {
                    const segAngle = closestSeg.angle;
                    const combinedRotation = segAngle + punchOrientation;

                    let perpOffset = selectedTool.height / 2;
                    if (Math.abs(punchOrientation % 180) > 45 && Math.abs(punchOrientation % 180) < 135) {
                        perpOffset = selectedTool.width / 2;
                        if (selectedTool.shape === ToolShape.Circle) perpOffset = selectedTool.width / 2; 
                    } else {
                        if (selectedTool.shape === ToolShape.Circle) perpOffset = selectedTool.width / 2;
                    }

                    const ux = Math.cos(segAngle * Math.PI / 180);
                    const uy = Math.sin(segAngle * Math.PI / 180);
                    const nx = -uy; 
                    const ny = ux;

                    const midX = (closestSeg.p1.x + closestSeg.p2.x) / 2;
                    const midY = (closestSeg.p1.y + closestSeg.p2.y) / 2;

                    // Initial test point: Center of tool on Positive Normal side
                    const testP = { 
                        x: midX + nx * perpOffset, 
                        y: midY + ny * perpOffset 
                    };

                    let finalOffsetSign = 1;
                    if (activePartProcessedGeometry) {
                        // Use the ACTUAL tool center relative to global coordinates for the Inside check.
                        // isPointInsideContour uses global coordinates. 
                        // bbox.minX/Y handles the translation from SVG (0,0 based) to Raw Dxf Coords if needed, 
                        // but isPointInsideContour implementation expects point in same space as Geometry.
                        // Our processedGeometry is usually normalized to (0,0). 
                        // activePart.geometry.bbox has minX/minY = 0 if normalized.
                        // However, to be safe, we denormalize if the original was shifted.
                        // In this app, `activePart.geometry` entities are normalized to (0,0)-(W,H).
                        // So `midX/midY` (from processedGeometry which is also normalized) are correct in that space.

                        // We check the center.
                        // If center is Inside (Material), we flip.
                        if (isPointInsideContour(testP, activePart.geometry)) {
                            finalOffsetSign = -1;
                        } else {
                            // Double check: Is the flipped position inside?
                            const flippedP = { x: midX - nx * perpOffset, y: midY - ny * perpOffset };
                            if (!isPointInsideContour(flippedP, activePart.geometry)) {
                                // Both centers are outside. This happens with thin gaps or concave shapes.
                                // We stick to default +Normal unless...
                                // Actually, for "Long tool exceeding line length", the problem is often 
                                // that the simple probe point logic fails.
                                // Here, using the exact tool center `testP` against the full polygon 
                                // is the most robust way to find "Material".
                                // If testP is NOT inside, we assume it's scrap (outside), so orientation is good.
                            }
                        }
                    }

                    const punches = generateNibblePunches(
                        closestSeg.p1, 
                        closestSeg.p2, 
                        selectedTool, 
                        nibbleSettings, 
                        closestSeg.angle, 
                        closestSeg.wasNormalized, 
                        combinedRotation, 
                        perpOffset * finalOffsetSign
                    );
                    onAddPunches(punches);
                }
                break;
            }
            case ManualPunchMode.Destruct: {
                if (punchCreationStep === 0) {
                    setPunchCreationPoints([finalPoint]);
                    setPunchCreationStep(1);
                } else {
                    const [startPoint] = punchCreationPoints;
                    const newPunchesData = generateDestructPunches(startPoint, finalPoint, selectedTool, destructSettings);
                    onAddPunches(newPunchesData);
                    // Reset locally, though parent might reset too via callback side-effect
                    setPunchCreationStep(0);
                    setPunchCreationPoints([]);
                }
                break;
            }
        }
    };

    // Helper to reset step externally if needed
    const resetManualState = () => {
        setPunchCreationStep(0);
        setPunchCreationPoints([]);
    };

    return { 
        handleCanvasClick, 
        punchCreationStep, 
        punchCreationPoints, 
        resetManualState,
        setPunchCreationPoints,
        setPunchCreationStep
    };
};

import { useMemo } from 'react';
import { Part, Tool, Point, ManualPunchMode, SnapMode, PlacementSide, ToolShape, NibbleSettings, PlacedTool } from '../types';
import { ProcessedGeometry, findClosestSegment, findSnapPoint, isPointInsideContour } from '../services/geometry';
import { calculateEdgePlacement } from '../services/placement';
// FIXED: Import generateNibblePunches from punchingGenerators instead of punching
import { generateNibblePunches } from '../services/punchingGenerators';

interface UseGhostPreviewProps {
    mousePos: Point | null;
    activePart: Part | null;
    processedGeometry: ProcessedGeometry | null;
    selectedTool: Tool | undefined;
    manualPunchMode: ManualPunchMode;
    snapMode: SnapMode;
    punchOrientation: number;
    punchOffset: number;
    nibbleSettings: NibbleSettings;
    punchCreationStep: number; // For Destruct mode hiding
    teachMode: boolean;
}

interface GhostPreviewResult {
    ghostPunches: { x: number, y: number, rotation: number }[];
    ghostLine: { x1: number, y1: number, x2: number, y2: number } | null;
    snapPoint: Point | null;
}

export const useGhostPreview = ({
    mousePos,
    activePart,
    processedGeometry,
    selectedTool,
    manualPunchMode,
    snapMode,
    punchOrientation,
    punchOffset,
    nibbleSettings,
    punchCreationStep,
    teachMode
}: UseGhostPreviewProps): GhostPreviewResult => {

    return useMemo(() => {
        if (!mousePos || !selectedTool || !activePart || teachMode) {
            return { ghostPunches: [], ghostLine: null, snapPoint: null };
        }

        if (manualPunchMode === ManualPunchMode.Destruct && punchCreationStep === 1) {
            return { ghostPunches: [], ghostLine: null, snapPoint: null }; // handled by separate logic or hidden
        }

        if (manualPunchMode === ManualPunchMode.Nibble) {
            const closestSeg = findClosestSegment(mousePos, processedGeometry);
            if (closestSeg) {
                const segAngle = closestSeg.angle;
                const combinedRotation = segAngle + punchOrientation;

                let perpOffset = selectedTool.height / 2;
                if (Math.abs(punchOrientation % 180) > 45 && Math.abs(punchOrientation % 180) < 135) {
                    perpOffset = selectedTool.width / 2;
                    if (selectedTool.shape === ToolShape.Circle) perpOffset = selectedTool.width / 2;
                } else {
                    if (selectedTool.shape === ToolShape.Circle) perpOffset = selectedTool.width / 2;
                }

                const ux = Math.cos(segAngle * Math.PI / 180);
                const uy = Math.sin(segAngle * Math.PI / 180);
                const nx = -uy;
                const ny = ux;

                const midX = (closestSeg.p1.x + closestSeg.p2.x) / 2;
                const midY = (closestSeg.p1.y + closestSeg.p2.y) / 2;
                const testP = { x: midX + nx * perpOffset, y: midY + ny * perpOffset };

                let finalOffsetSign = 1;

                if (processedGeometry) {
                    const rawTestP = {
                        x: testP.x + processedGeometry.bbox.minX,
                        y: processedGeometry.bbox.minY + testP.y 
                    };
                    if (isPointInsideContour(rawTestP, activePart.geometry)) {
                        finalOffsetSign = -1; 
                    }
                }

                const previewPunches = generateNibblePunches(
                    closestSeg.p1, 
                    closestSeg.p2, 
                    selectedTool, 
                    nibbleSettings, 
                    closestSeg.angle, 
                    closestSeg.wasNormalized, 
                    combinedRotation, 
                    perpOffset * finalOffsetSign
                );

                return {
                    ghostPunches: previewPunches.map(p => ({ x: p.x, y: p.y, rotation: p.rotation })),
                    ghostLine: { x1: closestSeg.p1.x, y1: closestSeg.p1.y, x2: closestSeg.p2.x, y2: closestSeg.p2.y },
                    snapPoint: null
                };
            }
            return { ghostPunches: [], ghostLine: null, snapPoint: null };
        }

        if (manualPunchMode === ManualPunchMode.Punch) {
            const snapResult = findSnapPoint(mousePos, processedGeometry, snapMode);
            if (!snapResult && snapMode !== SnapMode.Off) return { ghostPunches: [], ghostLine: null, snapPoint: null };

            const placementPoint = snapResult?.point ?? mousePos;
            let finalPlacement: { x: number, y: number, rotation: number };

            const isShapeCenter = snapResult && snapMode === SnapMode.ShapeCenter;

            if (isShapeCenter) {
                let rotation = punchOrientation;
                if (snapResult?.forceRotation !== undefined) {
                    const holeAngle = snapResult.forceRotation;
                    const isToolHorizontal = selectedTool.width >= selectedTool.height;

                    if (isToolHorizontal) {
                        rotation = holeAngle;
                    } else {
                        rotation = (holeAngle + 90) % 360;
                    }
                }
                finalPlacement = { x: placementPoint.x, y: placementPoint.y, rotation };
            } else {
                const placementAngle = snapResult?.angle ?? 0;

                const placementA = calculateEdgePlacement(
                    placementPoint, placementAngle, selectedTool, punchOrientation, punchOffset, 
                    snapResult?.snapTarget ?? 'middle', snapResult?.wasNormalized ?? false, PlacementSide.Outside
                );
                const placementB = calculateEdgePlacement(
                    placementPoint, placementAngle, selectedTool, punchOrientation, punchOffset, 
                    snapResult?.snapTarget ?? 'middle', snapResult?.wasNormalized ?? false, PlacementSide.Inside
                );

                finalPlacement = placementA;

                if (processedGeometry && activePart) {
                    const isInsideA = isPointInsideContour(placementA, activePart.geometry);
                    const isInsideB = isPointInsideContour(placementB, activePart.geometry);

                    if (!isInsideA && isInsideB) {
                        finalPlacement = placementA;
                    } else if (isInsideA && !isInsideB) {
                        finalPlacement = placementB;
                    } else {
                        finalPlacement = placementA;
                    }
                }
            }

            return {
                ghostPunches: [finalPlacement],
                ghostLine: null,
                snapPoint: snapResult ? snapResult.point : null
            };
        }

        return { ghostPunches: [], ghostLine: null, snapPoint: null };

    }, [mousePos, activePart, processedGeometry, selectedTool, manualPunchMode, snapMode, punchOrientation, punchOffset, nibbleSettings, punchCreationStep, teachMode]);
};

