import { Segment, isPointInsideContour, isToolGouging } from '../geometry';
import { Tool, AutoPunchSettings, PartGeometry, PlacedTool, ToolShape } from '../../types';
import { getPointKey } from '../punchingUtils';
import { getPreferredTools } from '../punchingTools';

export const processLine = (seg: Segment, geometry: PartGeometry, tools: Tool[], settings: AutoPunchSettings, jointVertices: Set<string>): Omit<PlacedTool, 'id'>[] => {
    const dx = seg.p2.x - seg.p1.x, dy = seg.p2.y - seg.p1.y, len = Math.sqrt(dx*dx + dy*dy);
    if (len < 0.1) return [];

    const candidates = getPreferredTools('line', len, 0, tools);
    if (candidates.length === 0) return [];
    const tool = candidates[0];

    const angle = Math.atan2(dy, dx) * 180 / Math.PI;
    const nx = -dy/len, ny = dx/len;
    const perp = (tool.shape === ToolShape.Circle ? tool.width : tool.height) / 2;
    const sign = isPointInsideContour({ x: (seg.p1.x+seg.p2.x)/2 + nx*perp*1.1, y: (seg.p1.y+seg.p2.y)/2 + ny*perp*1.1 }, geometry) ? -1 : 1;

    const ext1 = jointVertices.has(getPointKey(seg.p1)) ? -settings.microJointLength : settings.extension;
    const ext2 = jointVertices.has(getPointKey(seg.p2)) ? -settings.microJointLength : settings.extension;

    // Direct implementation of nibble logic for clarity
    const punches: Omit<PlacedTool, 'id'>[] = [];
    const effLen = len + ext1 + ext2;
    const step = Math.max(1, tool.width - settings.overlap);
    const hits = Math.ceil(effLen / step) + 1;
    const actualStep = (effLen - tool.width) / (hits - 1);

    for(let i=0; i<hits; i++) {
        const d = i * actualStep;
        punches.push({ toolId: tool.id, x: seg.p1.x - (dx/len)*ext1 + (dx/len)*(tool.width/2 + d) + nx*perp*sign, y: seg.p1.y - (dy/len)*ext1 + (dy/len)*(tool.width/2 + d) + ny*perp*sign, rotation: angle });
    }
    return punches.filter(p => !isToolGouging(tool, p.x, p.y, p.rotation, geometry, geometry.bbox, seg));
};

